fields.InputDefinition:
{
  "goal": "Open the Predictive Studio application using the application switcher dropdown next to the logo (scroll if needed). Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) new-prediction-copilot — on the 'Predictions' door, click the '+ New prediction' button (or 'Build your first prediction' in the empty state) and confirm a docked co-pilot chat panel slides in on the right, titled 'New prediction', with a Model Development Agent conversation area and a message composer (you do NOT need to send a message); (2) studio-ask-agent-copilot — open the 'Studio' door on the 'Overview' section and click the 'Ask the Model Dev Agent' hero button (or the 'Ask the agent' entry-path card), then confirm a docked co-pilot chat panel opens on the right titled 'Model Dev Agent' with a conversation area ready for input. Keep going until every section has been visited.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "new-prediction-copilot",
      "instruction": "open the '+ New prediction' docked copilot on the Predictions door",
      "visualCriteria": [
        "Clicking '+ New prediction' opens a docked chat panel titled 'New prediction' on the right side containing a conversation/message input area for the Model Development Agent"
      ]
    },
    {
      "name": "studio-ask-agent-copilot",
      "instruction": "open the Studio door 'Ask the Model Dev Agent' docked copilot",
      "visualCriteria": [
        "Clicking 'Ask the Model Dev Agent' on the Studio door opens a docked chat panel titled 'Model Dev Agent' on the right of the Studio workbench with a conversation/message area"
      ]
    }
  ]
}
